        -- Upsert edu_providers
        MERGE INTO dbo.edu_providers AS target
        USING (
            SELECT DISTINCT SchoolName AS name FROM @ProgramData
        ) AS src
        ON target.name = src.name
        WHEN NOT MATCHED THEN
          INSERT (id, name, created_at, updated_at)
          VALUES (NEWID(), src.name, GETDATE(), GETDATE());

        -- Upsert programs
        MERGE INTO dbo.programs AS target
        USING (
            SELECT DISTINCT ProgramName AS title FROM @ProgramData
        ) AS src
        ON target.title = src.title
        WHEN NOT MATCHED THEN
          INSERT (id, title, createdAt, updatedAt)
          VALUES (NEWID(), src.title, GETDATE(), GETDATE());

        -- Upsert provider_programs
        MERGE INTO dbo.provider_programs AS target
        USING (
            SELECT
              pd.*,
              CASE WHEN LOWER(pd.OfferedOnline) = 'online' THEN 'Online' ELSE 'In-person' END AS locationType_mapped
            FROM @ProgramData AS pd
        ) AS src
        ON
            target.edu_provider_id = (SELECT id FROM dbo.edu_providers WHERE name = src.SchoolName)
         AND target.program_id       = (SELECT id FROM dbo.programs       WHERE title = src.ProgramName)
        WHEN NOT MATCHED THEN
          INSERT
            (training_program_id,
             program_id,
             edu_provider_id,
             getStartedUrl,
             cipCode,
             locationType,
             programLength,
             costSummary,
             fees,
             createdAt,
             updatedAt)
          VALUES
            (NEWID(),
             (SELECT id FROM dbo.programs       WHERE title = src.ProgramName),
             (SELECT id FROM dbo.edu_providers WHERE name  = src.SchoolName),
             src.getStartedUrl,
             src.Search_CIP,
             src.locationType_mapped,
             src.ProgramLength,
             src.costSummary,
             src.fees,
             GETDATE(),
             GETDATE());
    COMMIT;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK;
    THROW;
END CATCH;